/* @lc app=leetcode id=1878 lang=kotlin */
class Solution { fun getBiggestThree(grid: Array<IntArray>): IntArray = (grid.indices).flatMap { i -> (grid[0].indices).flatMap { j -> (0..maxOf(grid.size, grid[0].size)).filter { L -> i - L >= 0 && i + L < grid.size && j - L >= 0 && j + L < grid[0].size }.map { L -> if (L == 0) grid[i][j] else (0 until L).sumOf { k -> grid[i - L + k][j + k] + grid[i + k][j + L - k] + grid[i + L - k][j - k] + grid[i - k][j - L + k] } } } }.distinct().sortedDescending().take(3).toIntArray() }